using UnityEngine;using UnityEditor;using System;using System.IO;using System.Linq;using System.Globalization;using System.Collections.Generic;using FoodPop;
internal class CommandScript:IRunCommand {
// EN: Writes a read-only web manifest with explicit JSON to avoid serializing Unity scene objects on worker threads.
// VI: Ghi manifest web chỉ đọc bằng JSON tường minh, tránh serialize object scene trên luồng nền.
public void Execute(ExecutionResult result){string root="E:/FoodPop/Web/LevelStudio/public/studio/unity";var sprites=new List<string>();var used=new HashSet<string>();var fields=new List<string>();var renders=new List<string>();var components=new List<string>();var audio=new List<string>();var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();foreach(var path in AssetDatabase.GetDependencies(new[]{scene.path,"Assets/HotPot/Config/Resources/IngameConfig.asset"},true)){foreach(var s in AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>()){AssetDatabase.TryGetGUIDAndLocalFileIdentifier(s,out string g,out long id);var key=g+"_"+id;if(used.Add(key))sprites.Add("{\"key\":"+Q(key)+",\"name\":"+Q(s.name)+",\"url\":"+Q("unity/sprites/"+key+".png")+",\"width\":"+N(s.rect.width)+",\"height\":"+N(s.rect.height)+"}");}if(path.EndsWith(".wav")||path.EndsWith(".mp3")||path.EndsWith(".ogg"))audio.Add("{\"name\":"+Q(Path.GetFileNameWithoutExtension(path))+",\"url\":"+Q("unity/audio/"+AssetDatabase.AssetPathToGUID(path)+Path.GetExtension(path))+"}");}
foreach(var c in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Component>(true)).Where(c=>c!=null)){var r=c as SpriteRenderer;if(r!=null&&r.sprite!=null){AssetDatabase.TryGetGUIDAndLocalFileIdentifier(r.sprite,out string g,out long id);renders.Add("{\"name\":"+Q(r.name)+",\"sprite\":"+Q(g+"_"+id)+",\"x\":"+N(r.transform.position.x)+",\"y\":"+N(r.transform.position.y)+",\"sx\":"+N(r.transform.lossyScale.x)+",\"sy\":"+N(r.transform.lossyScale.y)+",\"order\":"+r.sortingOrder+"}");}if(c.GetType().Namespace!="FoodPop")continue;var values=new List<string>();var so=new SerializedObject(c);var p=so.GetIterator();while(p.Next(true)){if(p.propertyType==SerializedPropertyType.ObjectReference){if(p.objectReferenceValue is Sprite sp){AssetDatabase.TryGetGUIDAndLocalFileIdentifier(sp,out string g,out long id);fields.Add("{\"field\":"+Q(c.GetType().Name+"."+p.propertyPath)+",\"key\":"+Q(g+"_"+id)+"}");}}else if(p.depth==0){string v=null;if(p.propertyType==SerializedPropertyType.Float)v=N(p.floatValue);if(p.propertyType==SerializedPropertyType.Integer||p.propertyType==SerializedPropertyType.Enum)v=p.intValue.ToString();if(p.propertyType==SerializedPropertyType.Boolean)v=p.boolValue?"true":"false";if(v!=null)values.Add(Q(p.name)+":"+v);}}components.Add("{\"type\":"+Q(c.GetType().Name)+",\"data\":{"+string.Join(",",values)+"}}");}
File.WriteAllText(root+"/manifest.json","{\"sprites\":["+string.Join(",",sprites)+"],\"audio\":["+string.Join(",",audio)+"],\"renderers\":["+string.Join(",",renders)+"],\"components\":["+string.Join(",",components)+"],\"spriteFields\":["+string.Join(",",fields)+"]}");result.Log("Manifest verified: "+sprites.Count+" sprites, "+audio.Count+" audio, "+components.Count+" components.");}
// EN: Escapes a JSON string without touching scene serialization.
// VI: Escape chuỗi JSON mà không serialize scene.
private static string Q(string s){return "\""+s.Replace("\\","\\\\").Replace("\"","\\\"").Replace("\n","\\n").Replace("\r","\\r")+"\"";}
// EN: Formats numbers with invariant decimal separators for JSON.
// VI: Định dạng số dùng dấu thập phân thống nhất cho JSON.
private static string N(float n){return n.ToString(CultureInfo.InvariantCulture);}
}
